; Public GLAD-style entry points.
; The per-version loader routines below do the actual pointer loading.
PUBLIC gladLoadGLUserPtr
PUBLIC gladLoadGL


; C runtime functions used by the extension helper routines.
; These are external symbols; the linker must provide their implementations.
EXTERN free:PROC
EXTERN malloc:PROC
EXTERN strlen:PROC
EXTERN memcpy:PROC
EXTERN strstr:PROC
EXTERN strcmp:PROC

.code

gladLoadGLUserPtr PROC loadfunc:QWORD, userptr:QWORD
    ; RCX = loader callback, RDX = user pointer
    ; The existing per-version routines use the same two arguments.
    ; They are called in GL version order.
    mov r8, rdx
    mov r9, rcx

    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_1_0
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_1_1
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_1_2
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_1_3
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_1_4
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_1_5
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_2_0
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_2_1
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_3_0
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_3_1
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_3_2
    mov rcx, r9
    mov rdx, r8
    call glad_gl_load_GL_VERSION_3_3

    xor eax, eax
    ret
gladLoadGLUserPtr ENDP

gladLoadGL PROC loadfunc:QWORD
    xor edx, edx
    jmp gladLoadGLUserPtr
gladLoadGL ENDP

