glad_gl_free_extensions PROC
    ; Prologue
    sub rsp, 28h
    
    ; Check if exts_i is NULL
    cmp rcx, 0
    je glad_gl_free_extensions__end_function
    
    ; Initialize index to 0
    xor rax, rax
    
glad_gl_free_extensions__loop:
    ; Load the pointer from exts_i[index]
    mov rdx, qword ptr [rcx + rax*8]
    
    ; Check if the pointer is NULL
    test rdx, rdx
    je glad_gl_free_extensions__free_exts_i
    
    ; Free the memory at the pointer
    mov rcx, rdx
    call free
    
    ; Increment the index
    inc rax
    
    ; Repeat the loop
    jmp glad_gl_free_extensions__loop
    
glad_gl_free_extensions__free_exts_i:
    ; Free the memory at exts_i
    mov rcx, qword ptr [rsp + 30h]
    call free
    
    ; Set exts_i to NULL
    mov rcx, qword ptr [rsp + 30h]
    mov qword ptr [rcx], 0
    
glad_gl_free_extensions__end_function:
    ; Epilogue
    add rsp, 28h
    ret
glad_gl_free_extensions ENDP

glad_gl_get_extensions PROC
    ; Prologue
    sub rsp, 38h
    mov [rsp+28h], rcx   ; Save out_exts
    mov [rsp+30h], rdx   ; Save out_exts_i

    ; Check if glad_glGetStringi and glad_glGetIntegerv are not NULL
    cmp qword ptr [glad_glGetStringi], 0
    je glad_gl_get_extensions__return_zero
    cmp qword ptr [glad_glGetIntegerv], 0
    je glad_gl_get_extensions__return_zero
    
    ; Initialize index and num_exts_i
    xor r8d, r8d         ; index = 0
    xor r9d, r9d         ; num_exts_i = 0

    ; Call glad_glGetIntegerv(GL_NUM_EXTENSIONS, &num_exts_i)
    mov ecx, 821Dh
    lea rdx, [r9]
    call qword ptr [glad_glGetIntegerv]

    ; Allocate memory for exts_i
    mov r8, r9
    add r8, 1
    mov rax, r8
    shl rax, 3           ; sizeof(char*)
    call malloc
    mov [rsp+20h], rax   ; Save exts_i
    cmp rax, 0
    je glad_gl_get_extensions__return_zero

    ; Loop through extensions
glad_gl_get_extensions__loop:
    cmp r8d, r9d
    jge glad_gl_get_extensions__end_loop

    ; Call glad_glGetStringi(GL_EXTENSIONS, index)
    mov ecx, 1F03h
    mov edx, r8d
    call qword ptr [glad_glGetStringi]
    mov r10, rax         ; gl_str_tmp = rax

    ; Get length of gl_str_tmp
    mov rcx, r10
    call strlen
    inc rax
    mov r11, rax         ; len = rax

    ; Allocate memory for local_str
    mov rcx, r11
    call malloc
    cmp rax, 0
    je glad_gl_get_extensions__free_and_return_zero
    mov r12, rax         ; local_str = rax

    ; Copy gl_str_tmp to local_str
    mov rcx, r12
    mov rdx, r10
    mov r8, r11
    call memcpy

    ; Store local_str in exts_i[index]
    mov rax, [rsp+20h]
    mov [rax + r8*8], r12

    ; Increment index and repeat loop
    inc r8d
    jmp glad_gl_get_extensions__loop

glad_gl_get_extensions__end_loop:
    ; Null-terminate exts_i
    mov rax, [rsp+20h]
    mov qword ptr [rax + r8*8], 0

    ; Set *out_exts_i = exts_i
    mov rax, [rsp+30h]
    mov rdx, [rsp+20h]
    mov [rax], rdx

    ; Return 1
    mov rax, 1
    jmp glad_gl_get_extensions__epilogue

glad_gl_get_extensions__free_and_return_zero:
    mov rcx, [rsp+20h]
    call glad_gl_free_extensions

glad_gl_get_extensions__return_zero:
    xor rax, rax

glad_gl_get_extensions__epilogue:
    add rsp, 38h
    ret
glad_gl_get_extensions ENDP

glad_gl_has_extension PROC
    ; Prologue
    sub rsp, 28h
    mov [rsp+20h], rcx   ; Save exts
    mov [rsp+28h], rdx   ; Save exts_i
    mov [rsp+30h], r8    ; Save ext

    ; Check if exts_i is not NULL
    cmp qword ptr [rsp+28h], 0
    jne glad_gl_has_extension__check_extensions_i

    ; Handle the case where exts_i is NULL
    mov rax, [rsp+20h]
    cmp rax, 0
    je glad_gl_has_extension__return_zero

    mov rcx, [rsp+30h]
    cmp rcx, 0
    je glad_gl_has_extension__return_zero

    ; Loop through extensions string
glad_gl_has_extension__loop_extensions:
    mov rcx, [rsp+20h]  ; extensions
    mov rdx, [rsp+30h]  ; ext
    call strstr
    cmp rax, 0
    je glad_gl_has_extension__return_zero
    mov rdx, rax        ; loc = rax
    mov rcx, [rsp+30h]
    call strlen
    add rdx, rax        ; terminator = loc + strlen(ext)
    mov rcx, rdx
    sub rcx, [rsp+20h]  ; loc - extensions
    jz glad_gl_has_extension__match
    mov al, byte ptr [rdx]
    cmp al, 20h
    je glad_gl_has_extension__match
    cmp al, 0
    je glad_gl_has_extension__match
    mov rcx, rdx
    jmp glad_gl_has_extension__loop_extensions

glad_gl_has_extension__match:
    mov rax, 1
    jmp glad_gl_has_extension__epilogue

glad_gl_has_extension__check_extensions_i:
    ; Loop through exts_i
    xor r8d, r8d         ; index = 0
glad_gl_has_extension__loop_extensions_i:
    mov rax, [rsp+28h]
    mov rax, [rax + r8*8]
    cmp rax, 0
    je glad_gl_has_extension__return_zero
    mov rcx, rax
    mov rdx, [rsp+30h]
    call strcmp
    test rax, rax
    jz glad_gl_has_extension__found
    inc r8d
    jmp glad_gl_has_extension__loop_extensions_i

glad_gl_has_extension__found:
    mov rax, 1
    jmp glad_gl_has_extension__epilogue

glad_gl_has_extension__return_zero:
    xor rax, rax

glad_gl_has_extension__epilogue:
    add rsp, 28h
    ret
glad_gl_has_extension ENDP
